export type TelemetryMetadata = Readonly<Record<string, unknown>>
export type TelemetryRedactor = (value: unknown, key?: string | undefined) => unknown
export type MaybePromise<T> = T | Promise<T>

export interface TelemetryEvent {
  readonly name: string
  readonly time?: string | undefined
  readonly attributes?: TelemetryMetadata | undefined
  readonly durationMs?: number | undefined
}

export interface TelemetryWarning {
  readonly code: string
  readonly message: string
  readonly attributes?: TelemetryMetadata | undefined
}

export interface TelemetrySpan {
  readonly name: string
  readonly attributes?: TelemetryMetadata | undefined
}

export interface TelemetrySink {
  readonly event?: ((event: TelemetryEvent) => MaybePromise<void>) | undefined
  readonly warning?: ((warning: TelemetryWarning) => MaybePromise<void>) | undefined
}

export interface TelemetryOptions {
  readonly sink?: TelemetrySink | undefined
  readonly event?: ((event: TelemetryEvent) => MaybePromise<void>) | undefined
  readonly warning?: ((warning: TelemetryWarning) => MaybePromise<void>) | undefined
  readonly span?:
    | (<A>(span: TelemetrySpan, operation: () => Promise<A>) => MaybePromise<A>)
    | undefined
  readonly now?: (() => number) | undefined
  readonly redact?: TelemetryRedactor | undefined
}

export interface Telemetry {
  readonly event: (event: TelemetryEvent) => MaybePromise<void>
  readonly warning: (warning: TelemetryWarning) => MaybePromise<void>
  readonly span: <A>(span: TelemetrySpan, operation: () => Promise<A>) => MaybePromise<A>
  readonly redact: (value: unknown) => unknown
}

const identityRedactor: TelemetryRedactor = (value) => value

const redactTelemetryMetadata = (
  metadata: TelemetryMetadata | undefined,
  redact: TelemetryRedactor
): TelemetryMetadata | undefined => {
  if (!metadata) return undefined
  return Object.fromEntries(
    Object.entries(metadata).map(([key, value]) => [key, redact(value, key)])
  )
}

const withTime = (
  event: TelemetryEvent,
  now: () => number,
  redact: TelemetryRedactor
): TelemetryEvent => ({
  ...event,
  time: event.time ?? new Date(now()).toISOString(),
  attributes: redactTelemetryMetadata(event.attributes, redact),
})

const redactWarning = (warning: TelemetryWarning, redact: TelemetryRedactor): TelemetryWarning => ({
  ...warning,
  attributes: redactTelemetryMetadata(warning.attributes, redact),
})

const bestEffort = async (operation: () => MaybePromise<void>): Promise<void> => {
  try {
    await operation()
  } catch {
    // Telemetry must never alter SDK request behavior.
  }
}

const formatError = (error: unknown): string => {
  if (error instanceof Error) return error.stack ?? error.message
  try {
    return JSON.stringify(error)
  } catch {
    return String(error)
  }
}

export const makeTelemetry = (options: TelemetryOptions = {}): Telemetry => {
  const sink = options.sink
  const eventSink = options.event ?? sink?.event
  const warningSink = options.warning ?? sink?.warning
  const spanSink = options.span
  const now = options.now ?? Date.now
  const redact = options.redact ?? identityRedactor

  const event = async (input: TelemetryEvent): Promise<void> => {
    const prepared = withTime(input, now, redact)
    await bestEffort(async () => {
      await eventSink?.(prepared)
    })
  }

  const warning = async (input: TelemetryWarning): Promise<void> => {
    const prepared = redactWarning(input, redact)
    await bestEffort(async () => {
      await warningSink?.(prepared)
    })
  }

  const defaultSpan: Telemetry['span'] = async (input, operation) => {
    const startedAt = now()
    const baseAttributes = redactTelemetryMetadata(input.attributes, redact)
    await event({
      name: input.name + '.start',
      attributes: {
        ...(baseAttributes ?? {}),
        phase: 'start',
      },
    })

    try {
      const result = await operation()
      await event({
        name: input.name + '.finish',
        durationMs: now() - startedAt,
        attributes: {
          ...(baseAttributes ?? {}),
          phase: 'finish',
          outcome: 'success',
        },
      })
      return result
    } catch (error) {
      await event({
        name: input.name + '.finish',
        durationMs: now() - startedAt,
        attributes: {
          ...(baseAttributes ?? {}),
          phase: 'finish',
          outcome: 'failure',
          cause: formatError(error).slice(0, 500),
        },
      })
      throw error
    }
  }

  const span: Telemetry['span'] = spanSink
    ? async (input, operation) => await spanSink(input, operation)
    : defaultSpan

  return {
    event,
    warning,
    span,
    redact,
  }
}
