export class HarborClientConfigurationError extends Error {
  readonly code: 'missing_workspace_id' | 'ambiguous_workspace_id'

  constructor(code: 'missing_workspace_id' | 'ambiguous_workspace_id', message: string) {
    super(message)
    this.name = 'HarborClientConfigurationError'
    this.code = code
  }
}

export class HarborWorkspaceResolutionError extends HarborClientConfigurationError {}

const assertApiKeyWorkspaceId = (options: HarborPromiseClientOptions): void => {
  if (options.auth.kind === 'api_key' && !options.workspaceId) {
    throw new HarborClientConfigurationError(
      'missing_workspace_id',
      'Harbor API-key clients require workspaceId'
    )
  }
}

const generatedAuthOptions = (
  auth: HarborClientAuth
): {
  readonly bearerToken?: string | undefined
  readonly bearerTokenProvider?: HarborBearerTokenProvider | undefined
} => {
  if (auth.kind === 'bearer') {
    if (auth.tokenProvider) return { bearerTokenProvider: auth.tokenProvider }
    return { bearerToken: auth.token }
  }
  if (auth.keyProvider) return { bearerTokenProvider: auth.keyProvider }
  return { bearerToken: auth.key }
}

const makeClientTelemetry = (input: TelemetryOptions | undefined): Telemetry => makeTelemetry(input)

const randomHex = (bytes: number): string => {
  const buffer = new Uint8Array(bytes)
  if (globalThis.crypto) {
    globalThis.crypto.getRandomValues(buffer)
  } else {
    for (let index = 0; index < buffer.length; index++) {
      buffer[index] = Math.floor(Math.random() * 256)
    }
  }
  return Array.from(buffer, (byte) => byte.toString(16).padStart(2, '0')).join('')
}

const newTraceparent = (): string => '00-' + randomHex(16) + '-' + randomHex(8) + '-01'

const initHeaders = (init?: RequestInit): Headers => new Headers(init?.headers)

const withTraceparent = (init: RequestInit | undefined, traceparent: string): RequestInit => {
  const headers = initHeaders(init)
  if (!headers.has('traceparent')) headers.set('traceparent', traceparent)
  return { ...init, headers }
}

const urlPath = (input: RequestInfo | URL): string => {
  try {
    return new URL(String(input)).pathname
  } catch {
    return String(input)
  }
}

const urlHost = (input: RequestInfo | URL): string | undefined => {
  try {
    return new URL(String(input)).host
  } catch {
    return undefined
  }
}

const makeInstrumentedFetch = (
  fetchImpl: typeof fetch | undefined,
  telemetry: Telemetry
): typeof fetch | undefined => {
  if (!fetchImpl) return undefined
  return ((input, init) => {
    const headers = initHeaders(init)
    const traceparent = headers.get('traceparent') ?? newTraceparent()
    const method = init?.method ?? 'GET'
    const attributes: TelemetryMetadata = {
      'http.request.method': method,
      'url.path': urlPath(input),
      'server.address': urlHost(input),
      traceparent,
    }
    return Promise.resolve(
      telemetry.span(
        { name: 'harbor.client.http', attributes },
        async () => await fetchImpl(input, withTraceparent(init, traceparent))
      )
    )
  }) as typeof fetch
}

export const createHarborPromiseClient = (
  options: HarborPromiseClientOptions
): HarborPromiseClient => {
  assertApiKeyWorkspaceId(options)
  const telemetry = makeClientTelemetry(options.telemetry)
  const api = createHarborGeneratedClient({
    baseUrl: options.baseUrl,
    headers: options.headers,
    fetch: makeInstrumentedFetch(options.fetch ?? globalThis.fetch, telemetry),
    ...generatedAuthOptions(options.auth),
  })
  const resolveWorkspaceId = async (
    workspaceId: string | undefined,
    operation: string
  ): Promise<string> => {
    if (workspaceId) return workspaceId
    throw new HarborWorkspaceResolutionError(
      'missing_workspace_id',
      'Harbor ' + operation + ' requires workspace_id or a default HarborClient workspaceId'
    )
  }
  const withResolvedWorkspaceId = async (
    request: HarborRuntimeExecuteRequest,
    workspaceId: string | undefined
  ): Promise<ExecuteRequest> => ({
    ...request,
    workspace_id: await resolveWorkspaceId(request.workspace_id ?? workspaceId, 'runtime.execute'),
  })
  const withResolvedWorkspace = async <T extends { readonly workspace_id: string }>(
    request: WithOptionalWorkspace<T> | undefined,
    workspaceId: string | undefined,
    operation: string
  ): Promise<T> =>
    ({
      ...(request ?? {}),
      workspace_id: await resolveWorkspaceId(request?.workspace_id ?? workspaceId, operation),
    }) as T
  const withResolvedControlPlaneWorkspace = async <T extends HarborControlPlaneBody>(
    request: T | undefined,
    workspaceId: string | undefined,
    operation: string
  ): Promise<T & { readonly workspace_id: string }> =>
    ({
      ...(request ?? {}),
      workspace_id: await resolveWorkspaceId(request?.workspace_id ?? workspaceId, operation),
    }) as T & { readonly workspace_id: string }
  const controlPlaneCall =
    (workspaceId: string | undefined, path: string, operation: string): HarborControlPlaneCall =>
    async <
      TBody extends HarborControlPlaneBody = HarborControlPlaneBody,
      TResult = HarborControlPlaneResult,
    >(
      request?: TBody,
      init?: HarborRequestInit
    ) =>
      await api.requestJson<TResult>(
        {
          method: 'POST',
          path,
          body: await withResolvedControlPlaneWorkspace(request, workspaceId, operation),
        },
        init
      )
  const makeRuntime = (workspaceId: string | undefined): HarborRuntimeClient => ({
    execute: async (request, init) =>
      await api.executePlugin(await withResolvedWorkspaceId(request, workspaceId), init),
  })
  const makeTriggers = (workspaceId: string | undefined): HarborTriggersClient => ({
    inspect: async (request, init) =>
      await api.inspectTrigger(
        await withResolvedWorkspace<TriggerInspectBody>(request, workspaceId, 'triggers.inspect'),
        init
      ),
    activate: async (request, init) =>
      await api.activateTrigger(
        await withResolvedWorkspace<TriggerActivateBody>(request, workspaceId, 'triggers.activate'),
        init
      ),
    list: async (request, init) =>
      await api.listTriggers(
        await withResolvedWorkspace<TriggerListBody>(request, workspaceId, 'triggers.list'),
        init
      ),
    get: async (request, init) =>
      await api.getTrigger(
        await withResolvedWorkspace<TriggerGetBody>(request, workspaceId, 'triggers.get'),
        init
      ),
    pause: async (request, init) =>
      await api.pauseTrigger(
        await withResolvedWorkspace<TriggerPauseResumeBody>(request, workspaceId, 'triggers.pause'),
        init
      ),
    resume: async (request, init) =>
      await api.resumeTrigger(
        await withResolvedWorkspace<TriggerPauseResumeBody>(
          request,
          workspaceId,
          'triggers.resume'
        ),
        init
      ),
    disable: async (request, init) =>
      await api.disableTrigger(
        await withResolvedWorkspace<TriggerPauseResumeBody>(
          request,
          workspaceId,
          'triggers.disable'
        ),
        init
      ),
    replay: async (request, init) =>
      await api.replayTriggerDelivery(
        await withResolvedWorkspace<TriggerReplayBody>(request, workspaceId, 'triggers.replay'),
        init
      ),
    listDeliveries: async (request, init) =>
      await api.listTriggerDeliveries(
        await withResolvedWorkspace<TriggerDeliveriesListBody>(
          request,
          workspaceId,
          'triggers.deliveries.list'
        ),
        init
      ),
    getDelivery: async (request, init) =>
      await api.getTriggerDelivery(
        await withResolvedWorkspace<TriggerDeliveryGetBody>(
          request,
          workspaceId,
          'triggers.deliveries.get'
        ),
        init
      ),
    getLimits: async (request, init) =>
      await api.getTriggerLimits(
        await withResolvedWorkspace<TriggerLimitsGetBody>(
          request,
          workspaceId,
          'triggers.limits.get'
        ),
        init
      ),
    updateLimits: async (request, init) =>
      await api.updateTriggerLimits(
        await withResolvedWorkspace<TriggerLimitsUpdateBody>(
          request,
          workspaceId,
          'triggers.limits.update'
        ),
        init
      ),
  })
  const makeControlPlaneClients = (workspaceId: string | undefined): HarborControlPlaneClients => {
    const call = (path: string, operation: string): HarborControlPlaneCall =>
      controlPlaneCall(workspaceId, path, operation)
    return {
      sources: {
        list: call('/plugins/sources/list', 'sources.list'),
        get: call('/plugins/sources/get', 'sources.get'),
        add: call('/plugins/sources/add', 'sources.add'),
        refresh: call('/plugins/sources/refresh', 'sources.refresh'),
        remove: call('/plugins/sources/remove', 'sources.remove'),
        abandon: call('/plugins/sources/abandon', 'sources.abandon'),
        cleanupStale: call('/plugins/sources/cleanup-stale', 'sources.cleanupStale'),
        probe: call('/plugins/sources/probe', 'sources.probe'),
        authTest: call('/plugins/sources/auth-test', 'sources.authTest'),
        setVisibility: call('/plugins/sources/visibility/set', 'sources.visibility.set'),
        verification: {
          get: call('/plugins/sources/verification/get', 'sources.verification.get'),
          probe: call('/plugins/sources/verification/probe', 'sources.verification.probe'),
          set: call('/plugins/sources/verification/set', 'sources.verification.set'),
        },
      },
      registry: {
        list: call('/plugins/registry/list', 'registry.list'),
        install: call('/plugins/registry/install', 'registry.install'),
      },
      tools: {
        list: call('/plugins/tools/list', 'tools.list'),
        search: call('/plugins/tools/search', 'tools.search'),
        describe: call('/plugins/tools/describe', 'tools.describe'),
        schema: call('/plugins/tools/schema', 'tools.schema'),
        schemas: call('/plugins/tools/schemas', 'tools.schemas'),
        reindex: call('/plugins/tools/reindex', 'tools.reindex'),
        add: call('/plugins/tools/add', 'tools.add'),
      },
      credentials: {
        create: call('/plugins/credentials/create', 'credentials.create'),
        upsert: call('/plugins/credentials/upsert', 'credentials.upsert'),
        delete: call('/plugins/credentials/delete', 'credentials.delete'),
      },
      oauth: {
        start: call('/plugins/sources/oauth/start', 'oauth.start'),
        connect: call('/plugins/sources/oauth/connect', 'oauth.connect'),
        reconnect: call('/plugins/sources/oauth/reconnect', 'oauth.reconnect'),
        status: call('/plugins/sources/oauth/flow/status', 'oauth.status'),
        disconnect: call('/plugins/sources/oauth/disconnect', 'oauth.disconnect'),
        configure: call('/plugins/sources/oauth/configure', 'oauth.configure'),
        workspaceClients: {
          list: call('/plugins/oauth/workspace-clients/list', 'oauth.workspaceClients.list'),
          set: call('/plugins/oauth/workspace-clients/set', 'oauth.workspaceClients.set'),
          delete: call('/plugins/oauth/workspace-clients/delete', 'oauth.workspaceClients.delete'),
        },
      },
      runs: {
        list: call('/runs/list', 'runs.list'),
        get: call('/runs/get', 'runs.get'),
        graph: call('/runs/graph', 'runs.graph'),
        listArtifacts: call('/runs/artifacts/list', 'runs.artifacts.list'),
        create: call('/runs/create', 'runs.create'),
        complete: call('/runs/complete', 'runs.complete'),
        cancel: call('/runs/cancel', 'runs.cancel'),
        events: call('/runs/events', 'runs.events'),
      },
      policies: {
        rules: {
          list: call('/policies/rules/list', 'policies.rules.list'),
          get: call('/policies/rules/get', 'policies.rules.get'),
          create: call('/policies/rules/create', 'policies.rules.create'),
          update: call('/policies/rules/update', 'policies.rules.update'),
          delete: call('/policies/rules/delete', 'policies.rules.delete'),
        },
        effective: call('/policies/effective', 'policies.effective'),
        simulate: call('/policies/simulate', 'policies.simulate'),
        sourceGate: call('/policies/source-gate', 'policies.sourceGate'),
        listAudit: call('/policies/audit/list', 'policies.audit.list'),
      },
      audit: {
        list: call('/audit/list', 'audit.list'),
      },
      jobs: {
        list: call('/orbit/jobs/list', 'jobs.list'),
        inspect: call('/orbit/jobs/inspect', 'jobs.inspect'),
        publish: call('/orbit/jobs/publish', 'jobs.publish'),
        run: call('/orbit/jobs/run', 'jobs.run'),
        versions: call('/orbit/jobs/versions', 'jobs.versions'),
        disable: call('/orbit/jobs/disable', 'jobs.disable'),
        invocations: {
          list: call('/orbit/jobs/invocations/list', 'jobs.invocations.list'),
          get: call('/orbit/jobs/invocations/get', 'jobs.invocations.get'),
        },
      },
      apps: {
        list: call('/orbit/apps/list', 'apps.list'),
        inspect: call('/orbit/apps/inspect', 'apps.inspect'),
        publish: call('/orbit/apps/publish', 'apps.publish'),
        open: call('/orbit/apps/open', 'apps.open'),
        disable: call('/orbit/apps/disable', 'apps.disable'),
        updateAccess: call('/orbit/apps/access/update', 'apps.access.update'),
        activity: {
          list: call('/orbit/apps/activity/list', 'apps.activity.list'),
        },
        invocations: {
          list: call('/orbit/apps/invocations/list', 'apps.invocations.list'),
          get: call('/orbit/apps/invocations/get', 'apps.invocations.get'),
        },
      },
      workflows: {
        list: call('/workflows/list', 'workflows.list'),
        get: call('/workflows/get', 'workflows.get'),
        add: call('/workflows/add', 'workflows.add'),
        remove: call('/workflows/remove', 'workflows.remove'),
      },
    }
  }
  const runtime = makeRuntime(options.workspaceId)
  const triggers = makeTriggers(options.workspaceId)
  const controlPlane = makeControlPlaneClients(options.workspaceId)
  const workspaces: HarborWorkspacesClient = {
    list: async (request, init) => await api.listWorkspaces(request ?? {}, init),
    get: async (request, init) =>
      await api.getWorkspace(
        await withResolvedWorkspace(request, options.workspaceId, 'workspaces.get'),
        init
      ),
  }

  return {
    api,
    workspaces,
    workspace: (workspaceId) => ({
      id: workspaceId,
      runtime: makeRuntime(workspaceId),
      triggers: makeTriggers(workspaceId),
      ...makeControlPlaneClients(workspaceId),
    }),
    runtime,
    triggers,
    ...controlPlane,
  }
}

export type HarborClient = HarborPromiseClient
export type HarborClientOptions = HarborPromiseClientOptions

export const createHarborClient = createHarborPromiseClient

export interface HarborOAuthAuthorizeUrlOptions {
  readonly authorizationServerUrl: string
  readonly clientId: string
  readonly redirectUri: string
  readonly state: string
  readonly codeChallenge: string
  readonly scope?: readonly string[] | string | undefined
  readonly codeChallengeMethod?: 'S256' | 'plain' | undefined
  readonly resource?: string | undefined
  readonly organizationId?: string | undefined
}

const normalizeScope = (scope: readonly string[] | string | undefined): string =>
  typeof scope === 'string' ? scope : scope ? scope.join(' ') : 'openid profile email'

export const createHarborOAuthAuthorizeUrl = (options: HarborOAuthAuthorizeUrlOptions): URL => {
  const authorize = new URL(
    '/oauth2/authorize',
    options.authorizationServerUrl.replace(/\/+$/, '') + '/'
  )
  authorize.searchParams.set('client_id', options.clientId)
  authorize.searchParams.set('redirect_uri', options.redirectUri)
  authorize.searchParams.set('response_type', 'code')
  authorize.searchParams.set('scope', normalizeScope(options.scope))
  authorize.searchParams.set('state', options.state)
  authorize.searchParams.set('code_challenge', options.codeChallenge)
  authorize.searchParams.set('code_challenge_method', options.codeChallengeMethod ?? 'S256')
  if (options.resource) authorize.searchParams.set('resource', options.resource)
  if (options.organizationId) authorize.searchParams.set('organization_id', options.organizationId)
  return authorize
}
