type EffectError = unknown

type Effectify<T> = T extends (...args: infer Args) => Promise<infer Result>
  ? (...args: Args) => Effect.Effect<Result, EffectError>
  : T extends (...args: infer Args) => infer Result
    ? (...args: Args) => Effectify<Result>
    : T extends object
      ? { readonly [Key in keyof T]: Effectify<T[Key]> }
      : T

