export type HarborEffectClient = Effectify<HarborPromiseClient>
export type HarborClient = HarborEffectClient

const isPromiseLike = (value: unknown): value is Promise<unknown> =>
  !!value &&
  (typeof value === 'object' || typeof value === 'function') &&
  'then' in value &&
  typeof (value as { readonly then?: unknown }).then === 'function'

const toEffectClient = <T>(value: T): Effectify<T> => {
  if (typeof value === 'function') {
    return ((...args: readonly unknown[]) => {
      try {
        const result = (value as (...innerArgs: readonly unknown[]) => unknown)(...args)
        if (isPromiseLike(result)) {
          return Effect.tryPromise({
            try: async () => await result,
            catch: (error) => error,
          })
        }
        return toEffectClient(result)
      } catch (error) {
        return Effect.fail(error)
      }
    }) as Effectify<T>
  }

  if (!value || typeof value !== 'object') return value as Effectify<T>

  const output: Record<PropertyKey, unknown> = {}
  for (const key of Reflect.ownKeys(value)) {
    output[key] = toEffectClient((value as Record<PropertyKey, unknown>)[key])
  }
  return output as Effectify<T>
}

export const createHarborEffectClient = (options: HarborEffectClientOptions): HarborEffectClient =>
  toEffectClient(createHarborPromiseClient(options))

const HarborClientTag = Context.Service<HarborEffectClient>('@hrbr/client/effect/HarborClient')

export const HarborClient = Object.assign(HarborClientTag, {
  layer: (options: HarborEffectClientOptions) =>
    Layer.succeed(HarborClientTag, createHarborEffectClient(options)),
})
